

# =====================================================================
# THE CELLS OF CHAPTER 18 — F5 the priests' dues, F6 the Levite at the place, F7 the diviners, F8 the prophet
# =====================================================================
def the_priests_dues(case, data):
    """F5 — Deut 18:1-5 — THE LINE priests_dues_declared writing shoulder_cheeks_maw_owed, first_fleece_owed, priests_standing_chosen (STATUSES); Mishnah Chullin 10:4 and 11:2 the exam rows; Numbers 18 by CALL (korach), 10:8-9 by CALL (second_tablets); 18:2's receipt behind (portion_declared at Numbers 18:20)"""
    del P_[:]
    ask = case['ask']
    if ask == 'no_portion_no_inheritance':
        ink('18:1-2', '"THE PRIESTS THE LEVITES, ALL THE TRIBE OF LEVI, SHALL HAVE NO PORTION OR INHERITANCE with Israel … THE LORD IS HIS INHERITANCE, AS HE SPOKE TO HIM" — 18:2 shares %d tokens in order with 10:9 %s (the reading\'s assert); inheritance_barred on %s the tape\'s entries' % (TWIN['18:2 vs 10:9'], SHARED(DV(18, 2), DV(10, 9)), INHERIT_SCAN))
        move('the Sifrei 163:1-3, 164:1-3 (read whole at the reading); cold_run_korach (CALL) — KO.no_inheritance = %s; cold_run_second_tablets (CALL) — ST.levi_has_no_portion = %s, ST.as_the_lord_spoke_to_him = %s' % (KO_NOINH[1], ST_PORTION[:40], ST_SPOKE[:40]), "'all the tribe of Levi' — the blemished included (163:1); 'PORTION' — the spoil; 'INHERITANCE' — the land (163:2-3); the inheritance of the three and of the five (164:1-2); 'as He spoke to him' — to tell what caused it (164:3): A RECEIPT BEHIND — Numbers 18:20's line (portion_declared: inheritance_barred TWO on aaron and the_levites THE TAPE'S REFERENCE, never a second write; Onkelos 'the gifts He gave him' at both seats)")
        dat("no portion no inheritance a DATA row (the spoil, the land, the three and the five — the references on the tape; the receipt's referent behind); the exam's person the Levite who claims a share of the spoil — barred from it (Numbers 31's shares the tape's own line)")
        return out("no portion, no inheritance (18:1-2) — the spoil and the land, the three and the five, 'as He spoke to him' Numbers 18:20's line behind (the Sifrei 163:1-3, 164:1-3; korach's %s and second_tablets' receipt by CALL — no second write): the Levite who claims a share of the spoil barred from it" % (KO_NOINH[1][0],), ['barred_from_it'])
    if ask == 'the_fire_offerings_and_the_boundarys_holy_things':
        ink('18:1', '"THE FIRE OFFERINGS OF THE LORD AND HIS INHERITANCE THEY SHALL EAT" — "fire offerings" %s; "they shall eat" %s' % ([x for x in W(18, 1) if x == 'אשי'], [x for x in W(18, 1) if x == 'יאכלון']))
        move('the Sifrei 163:4 (read whole at the reading); cold_run_korach (CALL) — KO.twenty_four = %s, KO.most_holy_list = %s' % (KO_24[0][:40], KO_MOST[1]), "'THE FIRE OFFERINGS OF THE LORD' — these are the sanctuary's holy things; the boundary's holy things — whence? 'AND HIS INHERITANCE THEY SHALL EAT' (163:4): THE TWENTY-FOUR GIFTS — twelve in the sanctuary, twelve in the borders (Numbers 18's grant by CALL; priestly_dues_granted on aaron the tape's entry)")
        dat("the fire offerings and the boundary's holy things a DATA row (the sanctuary's twelve, the borders' twelve — korach's cell); the exam's person the priest who eats the boundary's holy things outside the sanctuary — accepted")
        return out("the fire offerings and the boundary's holy things (18:1) — the sanctuary's and the borders', the twenty-four (the Sifrei 163:4; korach's %s by CALL): the priest who eats the boundary's holy things outside the sanctuary accepted" % (KO_24[0][:2],), ['accepted'])
    if ask == 'the_due_exacted_by_judges':
        ink('18:3', '"AND THIS SHALL BE THE DUE OF THE PRIESTS from the people, from those who slaughter the slaughter, whether ox or sheep" — "the due" %s (the word of judgment); "from the people" %s' % ([x for x in W(18, 3) if x == 'משפט'], [x for x in W(18, 3) if x == 'העם']))
        move('the Sifrei 165:1-3 (read whole at the reading); cold_run_korach (CALL) — KO.breast_and_thigh = %s' % (KO_BT[0][:50],), "'DUE' — TEACHES THAT THE GIFTS ARE EXACTED BY JUDGES (165:1 — enforceable in court); might the consecrated owe the gifts? if the common, not liable to the breast and thigh, owe the gifts, the consecrated how much more? the teaching says 'and this shall be the due' — the a fortiori refused (165:2 — the breast and thigh the consecrated's, korach by CALL); 'FROM THE PEOPLE' — not from others, not from the priests (165:3)")
        dat("THE PARAMETER the_payer_class (the people — not gentiles, not priests; the common animal, not the consecrated; exacted by judges); the exam's person the priest who slaughters his own ox — exempt")
        return out("the due exacted by judges (18:3) — enforceable in court, on the common animal not the consecrated, from the people not the priests (the Sifrei 165:1-3; korach's breast and thigh by CALL): the priest who slaughters his own ox exempt", ['exempt'])
    if ask == 'the_claim_at_the_slaughter_and_the_proselytes_cow':
        ink('18:3', '"from those who SLAUGHTER THE SLAUGHTER … he shall give the priest THE SHOULDER AND THE CHEEKS AND THE MAW" — the doubled root %s; the three gifts %s; the deer and the gazelle exempt (71:9)' % ([x for x in W(18, 3) if x in ('זבחי', 'הזבח')], [x for x in W(18, 3) if x in ('הזרע', 'והלחיים', 'והקבה')]))
        move('the Sifrei 165:4-5, 71:9 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew); MISHNAH CHULLIN 10:4 (read whole at the design — THE EXAM ROW)', "'from those who slaughter the slaughter' — excluding the torn (165:4); HE HAS A CLAIM ONLY AT THE HOUR OF SLAUGHTER — from here they said: A PROSELYTE WHO CONVERTED AND HAD A COW — slaughtered before he converted, exempt; after, liable; in doubt, exempt — WHO CLAIMS FROM HIS FELLOW BEARS THE PROOF (165:5 = Chullin 10:4); the foreleg from the knee's joint to the shoulder-blade (the nazirite's), the thigh its counterpart (R. Judah to the upper joint), the jaw to the windpipe's ring (the Mishnah's own continuation); the deer and the gazelle exempt — 'like the deer' (71:9)")
        dat("THE WRITE shoulder_cheeks_maw_owed — a STATUS on israel_people at the chapters' own day (DI2); THE PARAMETER the_claims_instant (Chullin 10:4 — born at the slaughter; the doubt exempt, the burden on the claimant; the members' bounds); the exam's person the convert whose cow was slaughtered in doubt — exempt")
        return out("the claim at the slaughter and the proselyte's cow (18:3) — the torn excluded, the claim born at the slaughter's instant, the doubt exempt with the burden on the claimant, the foreleg and the jaw bounded (the Sifrei 165:4-5 = Mishnah Chullin 10:4 — the exam row read whole; 71:9 the deer): THE WRITE shoulder_cheeks_maw_owed, a STATUS on Israel at the chapters' own day; the convert whose cow was slaughtered in doubt exempt", ['shoulder_cheeks_maw_owed'])
    if ask == 'in_and_outside_the_land':
        ink('18:3', '"WHETHER OX OR SHEEP" — the pair %s; the mixed included' % ([x for x in W(18, 3) if x in ('שור', 'שה')],))
        move('the Sifrei 165:6-9 (read whole at the reading)', "'whether ox or sheep' — to include the mixed; in the land or outside it? IS IT NOT LOGIC? liable here and in the first fleece — as the fleece applies everywhere so the gifts; or: liable here and in the first heave offering — as that only in the land so these (165:6); let us see which it resembles — a thing not dependent on the land or on holiness from its like; let the heave offering not prove (165:7); or a thing that applies to many and few from its like; let the fleece not prove (165:8); THE TEACHING SAYS 'whether ox or sheep' — in the land or outside it: THE VERSE DECIDES what the analogies could not (165:9 — Chullin 10:1)")
        dat("THE PARAMETER the_gifts_everywhere (in and outside the land — the verse's decision after two analogies argued both ways); the exam's person the slaughterer outside the land — accepted, liable to the gifts")
        return out("in and outside the land (18:3) — two analogies argued both ways and the verse deciding: the gifts everywhere (the Sifrei 165:6-9 — Chullin 10:1): the slaughterer outside the land accepted, liable", ['accepted'])
    if ask == 'the_three_gifts_named':
        ink('18:3', '"AND HE SHALL GIVE THE PRIEST the shoulder and the cheeks and the maw" — "the shoulder" %s (the consonants Balaam\'s arm elsewhere — the reading\'s assert), "the cheeks" %s (a dual), "the maw" %s' % ([x for x in W(18, 3) if x == 'הזרע'], [x for x in W(18, 3) if x == 'והלחיים'], [x for x in W(18, 3) if x == 'והקבה']))
        move('the Sifrei 165:10-14 (read whole at the reading)', "'and he shall give to the priest' — to the priest himself, no agent (165:10); 'the shoulder' — THE RIGHT SHOULDER (165:11); 'the cheeks' — the lower cheek (165:12); 'the maw' — as it sounds (165:13); R. Judah's expounders of marks: the shoulder for the hand ('he took a spear in his hand'), the cheeks for the prayer ('Phinehas stood and prayed'), the maw for the belly ('the woman through her belly' — Numbers 25:7-8): PHINEHAS'S THREE BY THE SHARED CONSONANTS (165:14 — the census carrying both, the reading's assert)")
        dat("THE PARAMETER the_three_gifts (the right shoulder, the lower cheek, the maw; to the priest himself); Phinehas's three a DATA row; the exam's person the one who gives the left shoulder — barred from it")
        return out("the three gifts named (18:3) — the right shoulder, the lower cheek, the maw as it sounds, to the priest himself; Phinehas's three by the consonants (the Sifrei 165:10-14): the one who gives the left shoulder barred from it", ['barred_from_it'])
    if ask == 'the_first_fruits_and_the_fleece':
        ink('18:4', '"THE FIRST OF YOUR GRAIN, YOUR WINE AND YOUR OIL, AND THE FIRST OF THE FLEECE OF YOUR FLOCK YOU SHALL GIVE HIM" — "first" twice %s; "the fleece of your flock" %s; Numbers 18:12\'s triad the kin (shared %d — the order reversed, the reading\'s assert)' % ([x for x in W(18, 4) if x in ('ראשית', 'וראשית')], [x for x in W(18, 4) if x in ('גז', 'צאנך')], SHN(DV(18, 4), ('Num', 18, 12))))
        move('the Sifrei 166:1-9 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew at 166:5 and by ibid. at 166:6); MISHNAH CHULLIN 11:2 (read whole at the design — THE EXAM ROW); cold_run_korach (CALL) — KO.the_best_triad = %s' % (KO_BEST[0][:50],), "'the first of your grain, your wine and your oil' — only from the choicest, kind for kind (166:1 — Numbers 18:12's grant by CALL); 'the first of the fleece' — not the washed-off, not the torn, in and outside the land (166:2-4); 'YOUR FLOCK' — not others': THE GENTILE'S FLOCK EXEMPT, the seller who kept some liable, else the buyer (166:5 = Chullin 11:2); 'you shall give him' — enough for a gift: FIVE SELAS IN JUDEA, TEN IN GALILEE, whitened not dyed, enough for a small garment (166:6 — ibid.); how many sheep? Shammai TWO EWES (Isaiah 7:21), Hillel FIVE (1 Samuel 25:18); R. Dosa's weight against the sages' any amount (the Mishnah's own line); R. AKIVA: 'the first of the fleece' — two, 'your flock' — four, 'you shall give him' — five, COUNTED OUT OF THE VERSE'S OWN WORDS (166:7-9)")
        dat("THE WRITE first_fleece_owed — a STATUS on israel_people at the chapters' own day (DI2); THE PARAMETER the_fleeces_threshold (two or five — both houses' arms; five selas; the gentile's flock exempt; dyed before given exempt); the exam's person the owner of four ewes who shears — exempt by Hillel's arm (the practice), liable by Shammai's")
        return out("the first fruits and the fleece (18:4) — the choicest kind for kind; the fleece not the washed, not the torn, everywhere; the gentile's flock exempt; five selas for a small garment; two ewes or five, R. Akiva's five from the verse (the Sifrei 166:1-9 = Mishnah Chullin 11:2 — the exam row read whole; korach's triad by CALL): THE WRITE first_fleece_owed, a STATUS on Israel at the chapters' own day; the owner of four ewes exempt by Hillel's arm", ['first_fleece_owed'])
    if ask == 'chosen_to_stand':
        ink('18:5', '"FOR THE LORD YOUR GOD CHOSE HIM OF ALL YOUR TRIBES TO STAND AND MINISTER in the name of the LORD, he and his sons all the days" — "to stand and minister" %s; 10:8\'s "to stand before the LORD to minister to Him" the twin (shared %d)' % ([x for x in W(18, 5) if x in ('לעמד', 'לשרת')], TWIN['18:5 vs 10:8']))
        move('the Sifrei 167:1-2 (read whole at the reading); cold_run_second_tablets (CALL) — ST.to_stand_and_minister = %s; cold_run_korach (CALL) — KO.stranger_death = %s (priestly_dues_granted on %s the tape\'s entry)' % (ST_STAND[:50], KO_STRANGER[1], DUES_SCAN), "'chose him of all your tribes' — TEACHES THAT SERVICE IS VALID ONLY STANDING; if he sat and ministered, his service is invalid (167:1 = 155:5; Zevachim 2:1's seated among the disqualified; sitting invalidates — second_tablets' cell by CALL); 'he and his sons all the days' — in the land and outside it (167:2 — the priesthood's choice everywhere)")
        dat("THE WRITE priests_standing_chosen — a STATUS on israel_people at the chapters' own day (DI2); the standing a PARAMETER (service only standing, everywhere); the exam's person the priest who ministers seated — barred from it, his service invalid")
        return out("chosen to stand (18:5) — service valid only standing, he and his sons everywhere (the Sifrei 167:1-2; second_tablets' stand-and-minister by CALL): THE WRITE priests_standing_chosen, a STATUS on Israel at the chapters' own day; the priest who ministers seated barred from it", ['priests_standing_chosen'])
    return 'no verdict in span', [], list(P_)


def the_levite_at_the_place(case, data):
    """F6 — Deut 18:6-8 — THE LINE levite_at_the_place_declared writing levite_service_at_the_place_permitted and equal_portions_commanded (STATUSES); Mishnah Zevachim 2:1 and Sukkah 5:7 the exam rows; the Levite in the gates by CALL (place_name), the watches by CALL (korach)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_levite_who_is_a_priest':
        ink('18:6-7', '"AND WHEN THE LEVITE COMES FROM ONE OF YOUR GATES, from all Israel where he sojourns … HE SHALL MINISTER" — "the Levite" %s; 18:6\'s "from one of your gates" NOT read by the parser (the number word behind its prefix — the reading\'s assert %s); levite_forsaking_barred on Israel %s UNMOVED' % ([x for x in W(18, 6) if x == 'הלוי'], PARSE.get((18, 6)), PN_LEVITE[1]))
        move('the Sifrei 168:1-2, 208:1 (read whole at the reading — 208:1 the outside row at 21:5); cold_run_place_name (CALL) — PN.lest_you_forsake_the_levite = %s, PN.the_levites_scope = %s' % (PN_LEVITE[1], PN_SCOPE[1]), "'and when the Levite comes' — might the verse speak of a Levite proper? 'from one of your gates' — those who did not take their gates elsewhere; the Levites, who took their gates elsewhere, are out; 'and he shall minister' — one fit to minister; the Levites, unfit to minister, are out: THE LEVITE HERE IS A PRIEST (168:1 — 208:1 the same at 21:5); 'from all Israel where he sojourns' — in all the places of their dwellings (168:2); 12:12's Levite within your gates the other Levite (place_name by CALL)")
        dat("the Levite who is a priest a DATA row (18:6's Levite the priest; the tribe's Levites out by two exclusions; the origin unconstrained); the exam's person the Levite proper who comes to minister at the altar — barred from it")
        return out("the Levite who is a priest (18:6-7) — the two exclusions, the priest from all the places of their dwellings (the Sifrei 168:1-2, 208:1; place_name's Levite %s by CALL — no second write): the Levite proper who comes to minister at the altar barred from it" % (PN_LEVITE[1][0],), ['barred_from_it'])
    if ask == 'all_the_desire_of_his_soul':
        ink('18:6', '"AND COMES WITH ALL THE DESIRE OF HIS SOUL to the place which the LORD will choose" — the phrase %s (12:15, 12:20-21\'s "desire of your soul" the kin); the place formula\'s third seat in the chapters' % ([x for x in W(18, 6) if x in ('בכל', 'אות', 'נפשו')],))
        move('the Sifrei 168:3-4 (read whole at the reading); cold_run_korach (CALL) — KO.watch_places = %s, KO.lots = %s' % (KO_PLACES[0][:40], KO_LOTS[0][:40]), "WHENCE THAT A PRIEST COMES AND LIFTS HIS HANDS AT A WATCH NOT HIS OWN? 'and comes with all the desire of his soul' (168:3); whence that ALL THE WATCHES ARE EQUAL in the festival's offerings that come because of the festival? the same; always? 'FROM ONE OF YOUR GATES' — WHEN ISRAEL IS GATHERED IN ONE GATE, AT THE THREE FEASTS (168:4); the watches' three places and the four lots by CALL (korach)")
        dat("THE WRITE levite_service_at_the_place_permitted — a STATUS on israel_people at the chapters' own day (DI2); THE PARAMETER the_watches_equality (the festival's own offerings, at the three feasts, when Israel is gathered in one gate); the exam's person the priest of another watch who blesses at the festival — accepted")
        return out("all the desire of his soul (18:6) — the blessing at another watch; the watches equal only in the festival's own offerings, 'one of your gates' one gate for all Israel at the three feasts (the Sifrei 168:3-4; korach's watches by CALL): THE WRITE levite_service_at_the_place_permitted, a STATUS on Israel at the chapters' own day; the priest of another watch who blesses at the festival accepted", ['levite_service_at_the_place_permitted'])
    if ask == 'on_the_floor':
        ink('18:7', '"and he shall minister in the name of the LORD his God like all his brothers the Levites WHO STAND THERE before the LORD" — "who stand" %s; 155:5 and 167:1 the standing' % ([x for x in W(18, 7) if x == 'העמדים'],))
        move('the Sifrei 169:1 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew); MISHNAH ZEVACHIM 2:1 (read whole at the design — THE EXAM ROW)', "'and he shall minister in the name of the LORD his God' — ON THE FLOOR: from here you say — the non-priest, the mourner, the immersed-that-day, the one lacking atonement, the one lacking vestments, the unwashed, the uncircumcised, the impure, THE SEATED, ONE STANDING ON VESSELS OR ON A BEAST OR ON HIS FELLOW'S FEET — INVALID (169:1 = Zevachim 2:1); the left hand — R. Simeon deems it fit; the blood spilled on the floor and gathered invalid; the ramp not opposite the base, above for below, inside for outside — invalid without cutting off (the Mishnah's own continuation)")
        dat("THE PARAMETER the_floor (Zevachim 2:1's disqualifications of the blood's reception; the left hand disputed); the exam's person the priest who receives the blood standing on a vessel — barred from it, the offering invalid")
        return out("on the floor (18:7) — the seated and the one on vessels, a beast or another's feet invalid with the rest of Zevachim 2:1's list (the Sifrei 169:1 = Mishnah Zevachim 2:1 — the exam row read whole): the priest who receives the blood standing on a vessel barred from it", ['barred_from_it'])
    if ask == 'portion_as_portion':
        ink('18:8', '"PORTION AS PORTION THEY SHALL EAT" — the phrase %s; 18:8 shares nothing in order with any verse (the reading\'s assert: KINC %s)' % ([x for x in W(18, 8) if x in ('חלק', 'כחלק', 'יאכלו')], KINC[(18, 8)]))
        move('the Sifrei 169:2 (read whole at the reading — the Mishnah cited in the spine\'s Hebrew); MISHNAH SUKKAH 5:7 (read whole at the design — THE EXAM ROW)', "WHENCE THAT ALL THE WATCHES ARE EQUAL IN THE FESTIVAL'S LIMBS AND IN THE DIVISION OF THE SHOWBREAD? 'portion as portion they shall eat' — a portion to eat, a portion to serve; THE PORTION OF EATING AS THE PORTION OF SERVICE (169:2 = Sukkah 5:7: at three times in the year all the watches equal; 'here is matzah, here is leaven' at the assembly; the fixed watch offers the dailies, the vows and the freewill offerings; a festival beside the Sabbath — all equal in the showbread)")
        dat("THE WRITE equal_portions_commanded — a STATUS on israel_people at the chapters' own day (DI2); the equality's three seasons a PARAMETER (Sukkah 5:7); the exam's person the fixed watch that keeps the festival's limbs to itself — barred from it")
        return out("portion as portion (18:8) — the portion of eating as the portion of service: all the watches equal in the festival's limbs and the showbread at the three feasts (the Sifrei 169:2 = Mishnah Sukkah 5:7 — the exam row read whole): THE WRITE equal_portions_commanded, a STATUS on Israel at the chapters' own day; the fixed watch that keeps the festival's limbs barred from it", ['equal_portions_commanded'])
    if ask == 'the_fathers_barter':
        ink('18:8', '"BESIDES HIS SALES ACCORDING TO THE FATHERS" — the phrase %s; ONKELOS writes the Sifrei\'s reading into the verse ("the watch that comes on the Sabbath, as the fathers ordained" — the reading\'s assert, one seat)' % ([x for x in W(18, 8) if x in ('לבד', 'ממכריו', 'על', 'האבות')],))
        move('the Sifrei 169:3 (read whole at the reading)', "might all the watches be equal in the festival's offerings that do NOT come because of the festival? 'besides his sales according to the fathers' — what did the fathers sell each other? 'YOU YOUR SABBATH AND I MY SABBATH' (169:3): THE FATHERS' BARTER OF SABBATHS — the fixed watch keeps what the festival did not bring; Onkelos concurring in the verse itself")
        dat("the fathers' barter a DATA row (the watches' exchange of Sabbaths; the non-festival offerings the fixed watch's; Onkelos's reading); the exam's person the visiting priest who claims the daily offering's portion at the festival — barred from it")
        return out("the fathers' barter (18:8) — 'you your Sabbath and I my Sabbath': the non-festival offerings the fixed watch's, Onkelos writing it into the verse (the Sifrei 169:3): the visiting priest who claims the daily's portion barred from it", ['barred_from_it'])
    return 'no verdict in span', [], list(P_)


def the_diviners(case, data):
    """F7 — Deut 18:9-14 — THE LINE diviners_barred writing abominations_learning_barred and the nine practitioners' BLOCKS and wholeness_commanded (a STATUS); Mishnah Sanhedrin 7:7 the exam row; Molech and the ghost by CALL (sanctions, holiness_b), the sorceress by CALL (ordinances), the inquiry and the fire by CALL (place_name), the abomination by CALL (seven_nations), no divination by CALL (balak), whole by CALL (pre_sinai)"""
    del P_[:]
    ask = case['ask']
    if ask == 'learn_to_understand_not_to_do':
        ink('18:9', '"when you come into the land … YOU SHALL NOT LEARN TO DO the abominations of those nations" — "to learn" and "to do" %s; foreign_rite_inquiry_barred on Israel %s UNMOVED' % ([x for x in W(18, 9) if x in ('תלמד', 'לעשות')], PN_INQ[1]))
        move('the Sifrei 170:1-3 (read whole at the reading); cold_run_place_name (CALL) — PN.lest_you_inquire_after_their_gods = %s; cold_run_seven_nations (CALL) — SN.abomination_to_the_lord = %s' % (PN_INQ[1], SN_ABOM[1]), "'when you come into the land' — the entry formula a third time (170:1); 'you shall not learn to do' — might you not be permitted to learn in order to teach and understand? 'TO DO' — TO DO YOU MAY NOT LEARN, BUT YOU MAY LEARN TO TEACH AND UNDERSTAND (170:3): THE CODE/DATA LAW'S OWN WARRANT — the diviners' arts read as data by the compile; 12:30's inquiry after their gods the twin block by CALL")
        dat("THE WRITE abominations_learning_barred — a BLOCK on israel_people at the chapters' own day (DI2); the exam's person the sage who studies the sorcerers' ways to judge them — accepted (learning to understand)")
        return out("learn to understand, not to do (18:9) — the entry formula, the learning barred only 'to do' (the Sifrei 170:1-3; place_name's inquiry %s and seven_nations' abomination by CALL): THE WRITE abominations_learning_barred, a BLOCK on Israel at the chapters' own day; the sage who studies the sorcerers' ways to judge them accepted" % (PN_INQ[1][0],), ['abominations_learning_barred'])
    if ask == 'the_court_warned_and_fire_with_molech':
        ink('18:10', '"THERE SHALL NOT BE FOUND AMONG YOU one who passes his son or his daughter through the fire" — "found" %s (148:1\'s witnesses, here the court); 18:10 shares nothing in order with Leviticus 20:2 (%d — the reading\'s assert)' % ([x for x in W(18, 10) if x == 'ימצא'], TWIN['18:10 vs Lev 20:2']))
        move('the Sifrei 171:1-3 (read whole at the reading); MISHNAH SANHEDRIN 7:7 (read whole at the design — THE EXAM ROW); cold_run_sanctions (CALL) — SA.molech(predicate) = %s, (seed_scope) = %s; cold_run_place_name (CALL) — PN.their_sons_and_their_daughters = %s, PN.no_molech_named = %s' % (SA_PRED, SA_SEED, PN_SONS[1], PN_MOLECH[1]), "'there shall not be found among you' — TO WARN THE COURT ABOUT IT (171:1); his son and daughter only? his son's son and daughter's son — Leviticus 20:4's 'of his seed' (171:2 — sanctions' seed scope by CALL); still I say: here fire, there Molech; 'PASSING' 'PASSING' AN ANALOGY: as here fire so there, as there Molech so here — NOT UNTIL HE HANDS OVER AND PASSES THROUGH FIRE AND TO MOLECH (171:3 = Sanhedrin 7:7: handed and not passed, passed and not handed — not liable); 12:31's sons in the fire without the king-word (place_name by CALL)")
        dat("THE WRITE passing_through_fire_barred — a BLOCK on israel_people at the chapters' own day (DI2); THE PARAMETER fire_and_molech (both required — Sanhedrin 7:7; the grandchildren included; the court warned); the exam's person the one who handed his son to Molech but did not pass him through the fire — exempt")
