def the_prophet(case, data):
    """F8 — Deut 18:15-22 — THE LINE prophet_law_declared writing prophet_like_moses_promised and word_required_of_the_hearer (HEAVEN entries), prophet_hearkening_commanded and false_word_test_declared (STATUSES), false_prophet_fear_barred (a BLOCK); chapter 13's prophet by CALL (seducers), Horeb by CALL (covenant_at_horeb, obey_horeb), the word in the mouth by CALL (balak); the false prophet's own verdict put_to_death; THE TEST BY THE EVENT a law whose verdict waits on the tape's future"""
    del P_[:]
    ask = case['ask']
    if ask == 'from_your_midst_of_your_brothers':
        ink('18:15, 18:18', '"A PROPHET FROM YOUR MIDST, OF YOUR BROTHERS, LIKE ME, the LORD your God will raise up FOR YOU" / "a prophet I will raise up for them from among their brothers like you" — "from your midst" and "of your brothers" %s (157:4-5\'s two exclusions again); prophet_declared on %s the tape\'s entry' % ([x for x in W(18, 15) if x in ('מקרבך', 'מאחיך')], PROPHET_SCAN))
        move('the Sifrei 175:1 (read whole at the reading)', "'a prophet from your midst' — and not from outside the land; 'of your brothers' — not from others; 'the LORD your God will raise up FOR YOU' — not for the nations; then how 'a prophet to the nations I made you' (Jeremiah 1:5)? one who behaves like the nations (175:1 — the king's two exclusions again at the prophet): the LORD's own undertaking a HEAVEN entry like the kings promised on Jacob")
        dat("THE WRITE prophet_like_moses_promised — a HEAVEN entry on israel_people at the chapters' own day (DI2); the exam's person the prophet from outside the land — accepted against (not the promised one); Abraham's prophet_declared the reference")
        return out("from your midst, of your brothers (18:15, 18:18) — not from outside the land, not from others, for you and not for the nations, Jeremiah resolved (the Sifrei 175:1): THE WRITE prophet_like_moses_promised, a HEAVEN entry on Israel at the chapters' own day; the prophet from outside the land accepted against", ['prophet_like_moses_promised'])
    if ask == 'hear_him_even_for_the_hour':
        ink('18:15', '"TO HIM YOU SHALL HEARKEN" — %s (Onkelos "you shall accept" — the reading\'s assert); false_prophet_hearing_barred on Israel %s the 13:4 twin' % ([x for x in W(18, 15) if x in ('אליו', 'תשמעון')], FALSEP_SCAN))
        move('the Sifrei 175:2 (read whole at the reading); cold_run_seducers (CALL) — SE.elijah_at_carmel = %s, SE.the_established_prophet = %s' % (SE_CARMEL[1], SE_ESTAB[1]), "'to him you shall hearken' — EVEN IF HE TELLS YOU TO TRANSGRESS ONE OF THE COMMANDMENTS SAID IN THE TORAH, LIKE ELIJAH ON MOUNT CARMEL — FOR THE HOUR — OBEY HIM (175:2; the seducers' Carmel row: the true prophet's temporary uprooting heeded, Yevamot 90b; the established prophet needs no sign, Sanhedrin 89b)")
        dat("THE WRITE prophet_hearkening_commanded — a STATUS on israel_people at the chapters' own day (DI2); the exam's person the established prophet who orders an altar outside the place for the hour — accepted, obeyed (Elijah's case)")
        return out("hear him even for the hour (18:15) — even to transgress a commandment for the hour, like Elijah on Carmel (the Sifrei 175:2; seducers' Carmel %s and established prophet by CALL): THE WRITE prophet_hearkening_commanded, a STATUS on Israel at the chapters' own day; the established prophet's altar for the hour accepted" % (SE_CARMEL[1][0],), ['prophet_hearkening_commanded'])
    if ask == 'horebs_request_the_cause':
        ink('18:16-17', '"according to all you asked of the LORD your God AT HOREB on the day of the assembly, saying: let me not hear again the voice … and the LORD said to me: THEY HAVE DONE WELL in what they spoke" — 18:16 shares %d tokens in order with 5:25 %s and 18:17 %d with 5:28 %s (the reading\'s asserts); the tape\'s lines mediator_requested (5:23-27) and stand_here_commanded (5:28-31 — naming 18:16-17 forward)' % (TWIN['18:16 vs 5:25'], SHARED(DV(18, 16), DV(5, 25)), TWIN['18:17 vs 5:28'], SHARED(DV(18, 17), DV(5, 28))))
        move('the Sifrei 176:1-2 (read whole at the reading); cold_run_covenant_at_horeb (CALL) — CH.the_request = %s, CH.hear_and_do = %s; cold_run_obey_horeb (CALL) — OH.the_day_at_horeb = %s' % (CH_REQ[0][:50], CH_HEAR[0][:40], OH_DAY[0][:40]), "'according to all you asked at Horeb' — BY THIS THEY MERITED THAT PROPHETS STAND FOR THEM (176:1); 'they have done well in what they spoke' — THEY MATCHED MY MIND: 'a prophet I will raise up for them'; by the reward of the fear they feared, they merited prophets (176:2): HOREB'S REQUEST THE PROPHETS' CAUSE — 18:16-17 RETELL 5:24-28, the tape's own lines (the readback's REFERENCE rows, never a second act); the day of the assembly 4:10's (obey_horeb by CALL)")
        dat("Horeb's request a DATA row (the retelling's referent the tape's Deuteronomy 5 lines; the fear rewarded with prophets); the exam's person Israel at Horeb asking for a mediator — accepted, 'they have done well'")
        return out("Horeb's request the cause (18:16-17) — by the request they merited prophets, 'they have done well' — they matched My mind (the Sifrei 176:1-2; covenant_at_horeb's request %s and obey_horeb's day by CALL): the readback's REFERENCE rows against the tape's Deuteronomy 5 lines; Israel asking for a mediator accepted" % (CH_REQ[1][0],), ['accepted'])
    if ask == 'my_words_in_his_mouth':
        ink('18:18', '"and I WILL PUT MY WORDS IN HIS MOUTH, and he shall speak to them ALL THAT I COMMAND HIM" — %s; Numbers 23:5, 23:16\'s "the LORD put a word in Balaam\'s mouth" the kin (balak\'s own cell names 18:18); Numbers 12:8\'s Moses the contrast' % ([x for x in W(18, 18) if x in ('ונתתי', 'דברי', 'בפיו')],))
        move('the Sifrei 176:3-5 (read whole at the reading); cold_run_balak (CALL) — BK.word_in_mouth_mode = %s, BK.DATA[gentile_prophets] = %s' % (BK_MOUTH[0][:60], BK_GENT['value']), "'I will put My words in his mouth' — My words I put in his mouth, but I DO NOT SPEAK WITH HIM FACE TO FACE (176:3 — Moses' 'mouth to mouth' the contrast; another word: know how the Holy Spirit is put in the prophets' mouth; Onkelos 'the words of My prophecy'); 'and he shall speak to them' — NOT TO SEAT AN INTERPRETER (176:4); 'all that I command him' — he says the first first and the last last (176:5 — the prophet's order); Balaam's word in the mouth an angel or a hook, a dispute (balak by CALL)")
        dat("THE PARAMETER the_prophets_order (no interpreter; the first first and the last last; not face to face — the Holy Spirit in the mouth); the exam's person the prophet who speaks through an interpreter — barred from it")
        return out("My words in his mouth (18:18) — not face to face, no interpreter, first things first (the Sifrei 176:3-5; balak's word-in-the-mouth by CALL): a parameter; the prophet who speaks through an interpreter barred from it", ['barred_from_it'])
    if ask == 'the_six_deaths':
        ink('18:19-20', '"the man who does not hearken to My words … I WILL REQUIRE IT OF HIM; but THE PROPHET WHO PRESUMES to speak a word in My name which I did not command him, or who speaks in the name of other gods — that prophet SHALL DIE" — "I will require" %s (Onkelos "My Memra will require" — the reading\'s assert); "shall die" %s; 18:19 shares %d with 13:4' % ([x for x in W(18, 19) if x in ('אנכי', 'אדרש')], [x for x in W(18, 20) if x == 'ומת'], TWIN['18:19 vs 13:4']))
        move('the Sifrei 177:1, 178:1 (read whole at the reading); cold_run_seducers (CALL) — SE.the_prophets_death = %s' % (SE_PDEATH[1],), "THREE DIE BY HEAVEN'S HAND: who suppresses his prophecy, like Jonah; who waives a prophet's words, like Micah's fellow; a prophet who transgresses his own words, like Iddo — from 18:19's 'I will require it of him'; AND THREE BY THE COURT: who prophesies what he did not hear, like Zedekiah son of Chenaanah; what was not said to him, like Hananiah son of Azzur; who prophesies in the name of an idol, even speaking the true law — from 18:20 (177:1); 'shall die' — AN UNSPECIFIED DEATH SAID IN THE TORAH IS STRANGULATION (178:1 = 155:7); chapter 13's prophet's death stoning or strangling the seducers' parameter by CALL")
        dat("THE WRITE word_required_of_the_hearer — a HEAVEN entry on israel_people at the chapters' own day (DI2 — the three deaths by Heaven); THE PARAMETER the_six_deaths (three by Heaven, three by the court — strangulation); the exam's person Hananiah who prophesied what was not said to him — put to death by the court (the body effect reused)")
        return out("the six deaths (18:19-20) — three by Heaven from 'I will require' (Jonah, Micah's fellow, Iddo), three by the court from 'shall die' (Zedekiah, Hananiah, the idol's prophet), strangulation the unspecified death (the Sifrei 177:1, 178:1; seducers' %s by CALL): THE WRITE word_required_of_the_hearer, a HEAVEN entry on Israel at the chapters' own day; Hananiah put to death by the court" % (SE_PDEATH[1][0],), ['word_required_of_the_hearer', 'put_to_death'])
    if ask == 'the_false_prophets_kin':
        ink('18:20, 13:2-6', '"who speaks in the name of other gods" — chapter 13\'s prophet with the sign against chapter 18\'s prophet with the word (18:22 shares %d with 13:2 — the reading\'s assert); false_prophet_hearing_barred %s and tested_by_the_lord on Israel the tape\'s 13:2 line' % (TWIN['18:22 vs 13:2'], FALSEP_SCAN))
        move('cold_run_seducers (CALL) — SE.the_prophet_and_the_dreamer = %s, SE.the_sign_and_the_wonder = %s, SE.the_false_prophets_table = %s, SE.the_evil_purged = %s' % (SE_DREAMER[:40], SE_SIGN[:40], SE_TABLE[1], SE_PURGED[1]), "THE TWO CHAPTERS ONE LAW — 13's sign that comes to pass yet preaches idolatry (not heeded: the LORD is testing you), 18's word that does not come to pass (not the LORD's); the false prophet's table — the essence abolished strangled, the part exempt, the hour heeded, idolatry even for a day liable (Sanhedrin 90a — the seducers' cell by CALL); false_prophet_hearing_barred ONE on Israel UNMOVED — referenced, not reused")
        dat("the false prophet's kin a DATA row (13:2-6's cells by CALL; the two tests — the sign and the word); the exam's person the prophet who preaches idolatry with a true sign — put to death (chapter 13's verdict by CALL) and the evil purged")
        return out("the false prophet's kin (18:20 with 13:2-6) — the sign against the word, one law in two chapters (seducers' table %s and death by CALL; the 13:2 line's block unmoved): the prophet who preaches idolatry with a true sign put to death and the evil purged" % (SE_TABLE[1][0],), ['put_to_death', 'evil_purged_from_the_midst'])
    if ask == 'the_test_by_the_event':
        ink('18:21-22', '"and if you say in your heart, HOW SHALL WE KNOW the word which the LORD has not spoken? what the prophet speaks in the name of the LORD AND THE THING DOES NOT COME TO PASS — that is the word the LORD has not spoken; PRESUMPTUOUSLY the prophet spoke it" — "how shall we know" %s; "presumptuously" %s (17:12 and 18:22 alone in the Torah — the reading\'s assert)' % ([x for x in W(18, 21) if x in ('איכה', 'נדע')], [x for x in W(18, 22) if x == 'בזדון']))
        move('the Sifrei 178:2 (read whole at the reading)', "'and if you say, how shall we know the word' — YOU WILL SAY IT: Jeremiah said 'the vessels of the house go to Babylon' (27:22) and Hananiah 'the vessels return from Babylon' (27:16) — whom shall I heed? the teaching says 'what the prophet speaks in the LORD's name and the thing does not come to pass — that is the word the LORD has not spoken' (178:2): THE TEST BY THE EVENT — A LAW WHOSE VERDICT WAITS ON THE TAPE'S FUTURE (the vessels' return the event; the readback's own question when the Prophets are on the tape — THE_LOOP step 6); presumptuously, not in error (155:3's rule at the prophet)")
        dat("THE WRITE false_word_test_declared — a STATUS on israel_people at the chapters' own day (DI2); THE PARAMETER the_test_by_the_event (the word graded by its coming to pass; its exercise the Prophets' tape — OWED under the debt line, no hypothesis: the ink names the test); the exam's person Hananiah whose word did not come to pass within its year — accepted against, the word not the LORD's")
        return out("the test by the event (18:21-22) — Jeremiah against Hananiah, the word graded by its coming to pass, presumptuously not in error (the Sifrei 178:2): THE WRITE false_word_test_declared, a STATUS on Israel at the chapters' own day — a law whose verdict waits on the tape's future; Hananiah's word that did not come to pass accepted against", ['false_word_test_declared'])
    if ask == 'no_fear_in_prosecuting':
        ink('18:22', '"YOU SHALL NOT FEAR HIM" — the negation %s; "you shall not fear" at one seat in this form (the reading\'s assert); 150:2\'s rule inverted' % ([x for x in W(18, 22) if x in ('לא', 'תגור')],))
        move('the Sifrei 178:3, 150:2 (read whole at the reading)', "'you shall not fear him' — DO NOT HOLD YOURSELF BACK FROM ARGUING HIS GUILT (178:3): the last clause a duty on the WITNESS — the fear of the prophet no bar to prosecuting him (150:2's 'one witness argues no guilt' inverted: here the witness must)")
        dat("THE WRITE false_prophet_fear_barred — a BLOCK on israel_people at the chapters' own day (DI2); no_fear a PARAMETER (the witness's duty to prosecute); the exam's person the witness who withholds the false prophet's guilt out of fear — barred from it")
        return out("no fear in prosecuting (18:22) — do not hold back from arguing his guilt, the witness's duty (the Sifrei 178:3; 150:2 inverted): THE WRITE false_prophet_fear_barred, a BLOCK on Israel at the chapters' own day; the witness who withholds the false prophet's guilt barred from it", ['false_prophet_fear_barred'])
    return 'no verdict in span', [], list(P_)
